// Handle extension — lengthens the fork stem; overlaps FORK_D's handle.
const FORK_HANDLE_D =
  'M 948 1740 L 1088 1740 L 1088 2010 Q 1088 2080 1018 2080 Q 948 2080 948 2010 Z';

type Props = {
  size?: number;
  className?: string;
};

export default function AnimatedLogo({ size = 32, className = '' }: Props) {
  // Bumping this key remounts the <svg>, which is the simplest way to
  // restart a CSS animation from frame 0 on hover.
  const [replayKey, setReplayKey] = useState(0);
  const replay = useCallback(() => setReplayKey((k) => k + 1), []);

  return (
    <span
      className={`inline-block align-middle ${className}`}
      style={{
        width: size,
        height: size,
        color: 'currentColor',
      }}
      onMouseEnter={replay}
    >
      <svg
        key={replayKey}
        viewBox="0 0 2048 2140"
        width={size}
        height={size}
        className="block"
        aria-hidden="true"
      >
        <g fill="currentColor">
          <g className="dr-logo-crown">
            <path d={CROWN_D} fillRule="evenodd" />
          </g>
          <g className="dr-logo-fork">
            <path d={FORK_D} fillRule="evenodd" />
            <path d={FORK_HANDLE_D} />
          </g>
        </g>
      </svg>
    </span>
  );
}
